1	"use server";
2	
3	import { redirect } from "next/navigation";
4	import { revalidatePath } from "next/cache";
5	import { getUser, requireRole } from "@/lib/auth";
6	import { createClient } from "@/lib/supabase/server";
7	import { createAdminClient } from "@/lib/supabase/admin";
8	import { getCalls } from "@/lib/integrations/calls";
9	import { getPayments } from "@/lib/integrations/payments";
10	import { computeSessionAccounting, roundHalfUp } from "@/lib/pricing";
11	import { type BlockMinutes } from "@/lib/pricing";
12	import { reviewSchema, type ReviewInput } from "@/lib/validation/schemas";
13	import { t } from "@/lib/i18n";
14	
15	async function loadBookingForParty(bookingId: string) {
16	  const user = await getUser();
17	  if (!user) redirect("/signin");
18	  const supabase = await createClient();
19	  const { data: booking } = await supabase
20	    .from("bookings")
21	    .select("*")
22	    .eq("id", bookingId)
23	    .maybeSingle();
24	  // RLS already restricts to a party; double-check defensively.
25	  if (
26	    !booking ||
27	    (booking.customer_id !== user.id && booking.provider_id !== user.id)
28	  ) {
29	    return null;
30	  }
31	  return booking;
32	}
33	
34	export interface StartSessionResult {
35	  sessionId?: string;
36	  error?: string;
37	}
38	
39	/**
40	 * Start (or re-join) the mock call for a booking. Idempotent: returns the
41	 * existing session if one already exists. Creates the call session via the
42	 * calls adapter and the sessions row via the service-role client.
43	 */
44	export async function startSession(
45	  bookingId: string,
46	): Promise<StartSessionResult> {
47	  const booking = await loadBookingForParty(bookingId);
48	  if (!booking) return { error: "This session isn't available." };
49	
50	  // Block the call if EITHER party is suspended — protects both sides,
51	  // independent of who initiated. A provider suspended via the approval queue
52	  // carries providers.status='suspended'; a user suspended by an admin carries
53	  // profiles.is_suspended. Read both via the service role since RLS hides each
54	  // party's row from the other.
55	  const admin = createAdminClient();
56	  const [{ data: parties }, { data: prov }] = await Promise.all([
57	    admin
58	      .from("profiles")
59	      .select("id, is_suspended")
60	      .in("id", [booking.customer_id, booking.provider_id]),
61	    admin
62	      .from("providers")
63	      .select("status")
64	      .eq("id", booking.provider_id)
65	      .maybeSingle(),
66	  ]);
67	  const eitherSuspended =
68	    (parties ?? []).some((p) => p.is_suspended) || prov?.status === "suspended";
69	  if (eitherSuspended) return { error: t("booking.suspended") };
70	
71	  const supabase = await createClient();
72	  const { data: existing } = await supabase
73	    .from("sessions")
74	    .select("id")
75	    .eq("booking_id", bookingId)
76	    .maybeSingle();
77	  if (existing) return { sessionId: existing.id };
78	
79	  const calls = getCalls();
80	  const { callSessionRef } = await calls.createSession({
81	    bookingId,
82	    providerId: booking.provider_id,
83	    customerId: booking.customer_id,
84	    maxMinutes: booking.block_minutes + 15,
85	  });
86	
87	  const { data: session, error } = await admin
88	    .from("sessions")
89	    .insert({
90	      booking_id: bookingId,
91	      provider_id: booking.provider_id,
92	      customer_id: booking.customer_id,
93	      call_session_ref: callSessionRef,
94	      started_at: new Date().toISOString(),
95	      block_minutes: booking.block_minutes,
96	      status: "in_progress",
97	    })
98	    .select("id")
99	    .single();
100	  if (error || !session) return { error: "We couldn't start the call." };
101	
102	  await supabase
103	    .from("bookings")
104	    .update({ status: "in_progress" })
105	    .eq("id", bookingId);
106	
107	  return { sessionId: session.id };
108	}
109	
110	export interface EndSessionResult {
111	  ok?: true;
112	  error?: string;
113	}
114	
115	/**
116	 * End the mock call. The client's count-up timer is the source of truth for
117	 * elapsed seconds (mock mode). Computes the final accounting (block + overage +
118	 * commission), captures the hold, and marks the session + booking completed.
119	 * Idempotent: a session already completed is left as-is.
120	 */
121	export async function endSession(
122	  bookingId: string,
123	  elapsedSeconds: number,
124	): Promise<EndSessionResult> {
125	  const booking = await loadBookingForParty(bookingId);
126	  if (!booking) return { error: "This session isn't available." };
127	
128	  const supabase = await createClient();
129	  const { data: session } = await supabase
130	    .from("sessions")
131	    .select("*")
132	    .eq("booking_id", bookingId)
133	    .maybeSingle();
134	  if (!session) return { error: "This session isn't available." };
135	  if (session.status === "completed") return { ok: true };
136	
137	  const elapsed = Math.max(0, Math.floor(elapsedSeconds || 0));
138	  const accounting = computeSessionAccounting({
139	    priceBlockCents: booking.price_block_cents,
140	    overagePerMinCents: booking.overage_per_min_cents,
141	    elapsedSeconds: elapsed,
142	    blockMinutes: booking.block_minutes as BlockMinutes,
143	  });
144	
145	  const calls = getCalls();
146	  if (session.call_session_ref) {
147	    await calls.endSession({ callSessionRef: session.call_session_ref });
148	  }
149	
150	  const payments = getPayments();
151	  if (booking.payment_ref) {
152	    await payments.capture({
153	      paymentRef: booking.payment_ref,
154	      amountCents: accounting.totalCents,
155	    });
156	  }
157	
158	  const admin = createAdminClient();
159	  const { error } = await admin
160	    .from("sessions")
161	    .update({
162	      ended_at: new Date().toISOString(),
163	      elapsed_seconds: elapsed,
164	      overage_minutes: accounting.overageMinutes,
165	      total_price_cents: accounting.totalCents,
166	      commission_cents: accounting.commissionCents,
167	      provider_earnings_cents: accounting.providerEarningsCents,
168	      status: "completed",
169	    })
170	    .eq("id", session.id);
171	  if (error) return { error: "We couldn't finish the call." };
172	
173	  await supabase
174	    .from("bookings")
175	    .update({ status: "completed" })
176	    .eq("id", bookingId);
177	
178	  return { ok: true };
179	}
180	
181	export interface ReviewResult {
182	  ok?: true;
183	  error?: string;
184	}
185	
186	/**
187	 * Submit a post-session review + optional tip. Inserts the review (RLS:
188	 * customer owns it), recomputes the provider's rating, and revalidates. Tips
189	 * carry no commission and are aggregated into payouts from the reviews table
190	 * (so they're not double-counted on the session row).
191	 */
192	export async function submitReview(input: ReviewInput): Promise<ReviewResult> {
193	  const profile = await requireRole("customer");
194	  const parsed = reviewSchema.safeParse(input);
195	  if (!parsed.success) return { error: "Please choose a rating." };
196	  const d = parsed.data;
197	
198	  const supabase = await createClient();
199	
200	  // The session must be the caller's own, completed.
201	  const { data: session } = await supabase
202	    .from("sessions")
203	    .select("id, customer_id, provider_id, status")
204	    .eq("id", d.sessionId)
205	    .maybeSingle();
206	  if (!session || session.customer_id !== profile.id) {
207	    return { error: "This session isn't available." };
208	  }
209	
210	  // One review per session.
211	  const { data: existing } = await supabase
212	    .from("reviews")
213	    .select("id")
214	    .eq("session_id", d.sessionId)
215	    .maybeSingle();
216	  if (existing) return { ok: true };
217	
218	  const { error: insErr } = await supabase.from("reviews").insert({
219	    session_id: d.sessionId,
220	    customer_id: profile.id,
221	    provider_id: session.provider_id,
222	    rating: d.rating,
223	    comment: d.comment ?? null,
224	    tip_cents: d.tipCents,
225	  });
226	  if (insErr) return { error: "We couldn't save your review." };
227	
228	  // Recompute the provider's rating (privileged column → service role).
229	  const admin = createAdminClient();
230	  const { data: ratings } = await admin
231	    .from("reviews")
232	    .select("rating")
233	    .eq("provider_id", session.provider_id);
234	  const count = ratings?.length ?? 0;
235	  const sum = (ratings ?? []).reduce((acc, r) => acc + r.rating, 0);
236	  const avg = count > 0 ? roundHalfUp((sum / count) * 100) / 100 : 0;
237	  await admin
238	    .from("providers")
239	    .update({ rating_avg: avg, rating_count: count })
240	    .eq("id", session.provider_id);
241	
242	  revalidatePath(`/session/${session.id}/summary`);
243	  revalidatePath("/provider/dashboard");
244	  return { ok: true };
